it('renders loading button and working select', () => {
  const btn = container.querySelector('button[data-part=root]');
  expect(btn).toBeTruthy(); expect(btn.textContent).toBe('保存');
  expect(btn.disabled).toBe(true); expect(btn.getAttribute('aria-busy')).toBe('true');
  const sel = container.querySelector('select[data-part=root]');
  expect(sel).toBeTruthy(); expect(sel.value).toBe('unsaved');
});
it('loading button click does not fire; select change fires', () => {
  const btn = container.querySelector('button[data-part=root]');
  let clicked = false; btn.addEventListener('click', () => { clicked = true; });
  btn.click(); expect(clicked).toBe(false);
  const sel = container.querySelector('select[data-part=root]');
  let changed = null; sel.addEventListener('change', () => { changed = sel.value; });
  sel.value = 'saved'; sel.dispatchEvent(new Event('change', { bubbles: true }));
  expect(changed).toBe('saved');
});
